// Parse OpenAI response and prepare data
const openAiResponse = $input.item.json;
const content = JSON.parse(openAiResponse.choices[0].message.content);
const product = $('🛍️ Select Product').item.json;

return [{
  json: {
    videoPrompt: content.videoPrompt,
    caption: content.caption,
    productLabel: product.label,
    productId: product.id,
    imageUrl: product.imageUrl,
    timestamp: product.timestamp
  }
}];

// Store request_id and pass forward all data
const falResponse = $input.item.json;
const prevData = $('📝 Parse AI Response').item.json;

return [{
  json: {
    requestId: falResponse.request_id,
    falQueueUrl: falResponse.response_url || `https://queue.fal.run/fal-ai/veo3/requests/${falResponse.request_id}`,
    videoPrompt: prevData.videoPrompt,
    caption: prevData.caption,
    productLabel: prevData.productLabel,
    productId: prevData.productId,
    imageUrl: prevData.imageUrl,
    timestamp: prevData.timestamp,
    pollAttempts: 0
  }
}];

// Check status and pass forward all previous data
const statusResponse = $input.item.json;
const prevData = $('💾 Save Request ID').item.json;

const status = statusResponse.status;
let videoUrl = null;

// Extract video URL if completed
if (status === 'COMPLETED' && statusResponse.output) {
  videoUrl = statusResponse.output.video?.url || statusResponse.output?.url || null;
}

return [{
  json: {
    status: status,
    videoUrl: videoUrl,
    requestId: prevData.requestId,
    caption: prevData.caption,
    productLabel: prevData.productLabel,
    productId: prevData.productId,
    timestamp: prevData.timestamp,
    pollAttempts: (prevData.pollAttempts || 0) + 1
  }
}];

// Find TikTok account (prefer @Cytron)
const accountsData = $input.item.json;
const accounts = Array.isArray(accountsData) ? accountsData : (accountsData.items ?? []);

const tiktokAccount = 
  accounts.find(a => a.platform === 'tiktok' && (
    a.username?.toLowerCase().includes('cytron') ||
    a.fullname?.toLowerCase().includes('cytron')
  )) ||
  accounts.find(a => a.platform === 'tiktok');

if (!tiktokAccount) {
  throw new Error('No TikTok account connected in Blotato!');
}

const videoData = $('📊 Parse Status').item.json;

return [{
  json: {
    accountId: tiktokAccount.id,
    username: tiktokAccount.username,
    videoUrl: videoData.videoUrl,
    caption: videoData.caption,
    productLabel: videoData.productLabel,
    timestamp: videoData.timestamp
  }
}];

